16	// Ensure ClaudeCodeAgent implements HookSupport
17	var _ agent.HookSupport = (*ClaudeCodeAgent)(nil)
18	
19	// Claude Code hook names - these become subcommands under `entire hooks claude-code`
20	const (
21		HookNameSessionStart     = "session-start"
22		HookNameSessionEnd       = "session-end"
23		HookNameStop             = "stop"
24		HookNameUserPromptSubmit = "user-prompt-submit"
25		HookNamePreTask          = "pre-task"
26		HookNamePostTask         = "post-task"
27		HookNamePostTodo         = "post-todo"
28	)
29	
30	// ClaudeSettingsFileName is the settings file used by Claude Code.
31	// This is Claude-specific and not shared with other agents.
32	const ClaudeSettingsFileName = "settings.json"
33	
34	// metadataDenyRule blocks Claude from reading Entire session metadata
35	const metadataDenyRule = "Read(./.entire/metadata/**)"
36	
37	// entireHookPrefixes are command prefixes that identify Entire hooks (both old and new formats)
38	var entireHookPrefixes = []string{
39		"entire ",
40		"go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go ",
41	}
42	
43	// InstallHooks installs Claude Code hooks in .claude/settings.json.
44	// If force is true, removes existing Entire hooks before installing.
45	// Returns the number of hooks installed.
46	func (c *ClaudeCodeAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
47		// Use repo root instead of CWD to find .claude directory
48		// This ensures hooks are installed correctly when run from a subdirectory
49		repoRoot, err := paths.WorktreeRoot(ctx)
50		if err != nil {
51			// Fallback to CWD if not in a git repo (e.g., during tests)
52			repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests run outside git repos)
53			if err != nil {
54				return 0, fmt.Errorf("failed to get current directory: %w", err)
55			}
56		}
57	
58		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
59	
60		// Read existing settings if they exist
61		var rawSettings map[string]json.RawMessage
62	
63		// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
64		var rawHooks map[string]json.RawMessage
65	
66		// rawPermissions preserves unknown permission fields (e.g., "ask")
67		var rawPermissions map[string]json.RawMessage
68	
69		existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + settings file name
70		if readErr == nil {
71			if err := json.Unmarshal(existingData, &rawSettings); err != nil {
72				return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
73			}
74			if hooksRaw, ok := rawSettings["hooks"]; ok {
75				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
76					return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
77				}
78			}
79			if permRaw, ok := rawSettings["permissions"]; ok {
80				if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
81					return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
82				}
83			}
84		} else {
85			rawSettings = make(map[string]json.RawMessage)
86		}
87	
88		if rawHooks == nil {
89			rawHooks = make(map[string]json.RawMessage)
90		}
91		if rawPermissions == nil {
92			rawPermissions = make(map[string]json.RawMessage)
93		}
94	
95		// Parse only the hook types we need to modify
96		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
97		parseHookType(rawHooks, "SessionStart", &sessionStart)
98		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
99		parseHookType(rawHooks, "Stop", &stop)
100		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
101		parseHookType(rawHooks, "PreToolUse", &preToolUse)
102		parseHookType(rawHooks, "PostToolUse", &postToolUse)
103	
104		// If force is true, remove all existing Entire hooks first
105		if force {
106			sessionStart = removeEntireHooks(sessionStart)
107			sessionEnd = removeEntireHooks(sessionEnd)
108			stop = removeEntireHooks(stop)
109			userPromptSubmit = removeEntireHooks(userPromptSubmit)
110			preToolUse = removeEntireHooksFromMatchers(preToolUse)
111			postToolUse = removeEntireHooksFromMatchers(postToolUse)
112		}
113	
114		// Define hook commands
115		var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, postTodoCmd string
116		if localDev {
117			sessionStartCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-start"
118			sessionEndCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-end"
119			stopCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop"
120			userPromptSubmitCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code user-prompt-submit"
121			preTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code pre-task"
122			postTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-task"
123			postTodoCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-todo"
124		} else {
125			sessionStartCmd = agent.WrapProductionJSONWarningHookCommand("entire hooks claude-code session-start", agent.WarningFormatMultiLine)
126			sessionEndCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code session-end")
127			stopCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code stop")
128			userPromptSubmitCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code user-prompt-submit")
129			preTaskCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code pre-task")
130			postTaskCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code post-task")
131			postTodoCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code post-todo")
132		}
133	
134		count := 0
135	
136		// Add hooks if they don't exist
137		if !hookCommandExists(sessionStart, sessionStartCmd) {
138			sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
139			count++
140		}
141		if !hookCommandExists(sessionEnd, sessionEndCmd) {
142			sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
143			count++
144		}
145		if !hookCommandExists(stop, stopCmd) {
146			stop = addHookToMatcher(stop, "", stopCmd)
147			count++
148		}
149		if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
150			userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
151			count++
152		}
153		if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
154			preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
155			count++
156		}
157		if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
158			postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
159			count++
160		}
161		if !hookCommandExistsWithMatcher(postToolUse, "TodoWrite", postTodoCmd) {
162			postToolUse = addHookToMatcher(postToolUse, "TodoWrite", postTodoCmd)
163			count++
164		}
165	
166		// Add permissions.deny rule if not present
167		permissionsChanged := false
168		var denyRules []string
169		if denyRaw, ok := rawPermissions["deny"]; ok {
170			if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
171				return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
172			}
173		}
174		if !slices.Contains(denyRules, metadataDenyRule) {
175			denyRules = append(denyRules, metadataDenyRule)
176			denyJSON, err := json.Marshal(denyRules)
177			if err != nil {
178				return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
179			}
180			rawPermissions["deny"] = denyJSON
181			permissionsChanged = true
182		}
183	
184		if count == 0 && !permissionsChanged {
185			return 0, nil // All hooks and permissions already installed
186		}
187	
188		// Marshal modified hook types back to rawHooks
189		marshalHookType(rawHooks, "SessionStart", sessionStart)
190		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
191		marshalHookType(rawHooks, "Stop", stop)
192		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
193		marshalHookType(rawHooks, "PreToolUse", preToolUse)
194		marshalHookType(rawHooks, "PostToolUse", postToolUse)
195	
196		// Marshal hooks and update raw settings
197		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
198		if err != nil {
199			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
200		}
201		rawSettings["hooks"] = hooksJSON
202	
203		// Marshal permissions and update raw settings
204		permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
205		if err != nil {
206			return 0, fmt.Errorf("failed to marshal permissions: %w", err)
207		}
208		rawSettings["permissions"] = permJSON
209	
210		// Write back to file
211		if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
212			return 0, fmt.Errorf("failed to create .claude directory: %w", err)
213		}
214	
215		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
216		if err != nil {
217			return 0, fmt.Errorf("failed to marshal settings: %w", err)
218		}
219	
220		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
221			return 0, fmt.Errorf("failed to write settings.json: %w", err)
222		}
223	
224		return count, nil
225	}
226	
227	// parseHookType parses a specific hook type from rawHooks into the target slice.
228	// Silently ignores parse errors (leaves target unchanged).
229	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]ClaudeHookMatcher) {
230		if data, ok := rawHooks[hookType]; ok {
231			//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
232			json.Unmarshal(data, target)
233		}
234	}
235	
236	// marshalHookType marshals a hook type back to rawHooks.
237	// If the slice is empty, removes the key from rawHooks.
238	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []ClaudeHookMatcher) {
239		if len(matchers) == 0 {
240			delete(rawHooks, hookType)
241			return
242		}
243		data, err := jsonutil.MarshalWithNoHTMLEscape(matchers)
244		if err != nil {
245			return // Silently ignore marshal errors (shouldn't happen)
246		}
247		rawHooks[hookType] = data
248	}
249	
250	// UninstallHooks removes Entire hooks from Claude Code settings.
251	func (c *ClaudeCodeAgent) UninstallHooks(ctx context.Context) error {
252		// Use repo root to find .claude directory when run from a subdirectory
253		repoRoot, err := paths.WorktreeRoot(ctx)
254		if err != nil {
255			repoRoot = "." // Fallback to CWD if not in a git repo
256		}
257		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
258		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
259		if err != nil {
260			return nil //nolint:nilerr // No settings file means nothing to uninstall
261		}
262	
263		var rawSettings map[string]json.RawMessage
264		if err := json.Unmarshal(data, &rawSettings); err != nil {
265			return fmt.Errorf("failed to parse settings.json: %w", err)
266		}
267	
268		// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
269		var rawHooks map[string]json.RawMessage
270		if hooksRaw, ok := rawSettings["hooks"]; ok {
271			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
272				return fmt.Errorf("failed to parse hooks: %w", err)
273			}
274		}
275		if rawHooks == nil {
276			rawHooks = make(map[string]json.RawMessage)
277		}
278	
279		// Parse only the hook types we need to modify
280		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
281		parseHookType(rawHooks, "SessionStart", &sessionStart)
282		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
283		parseHookType(rawHooks, "Stop", &stop)
284		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
285		parseHookType(rawHooks, "PreToolUse", &preToolUse)
286		parseHookType(rawHooks, "PostToolUse", &postToolUse)
287	
288		// Remove Entire hooks from all hook types
289		sessionStart = removeEntireHooks(sessionStart)
290		sessionEnd = removeEntireHooks(sessionEnd)
291		stop = removeEntireHooks(stop)
292		userPromptSubmit = removeEntireHooks(userPromptSubmit)
293		preToolUse = removeEntireHooksFromMatchers(preToolUse)
294		postToolUse = removeEntireHooksFromMatchers(postToolUse)
295	
296		// Marshal modified hook types back to rawHooks
297		marshalHookType(rawHooks, "SessionStart", sessionStart)
298		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
299		marshalHookType(rawHooks, "Stop", stop)
300		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
301		marshalHookType(rawHooks, "PreToolUse", preToolUse)
302		marshalHookType(rawHooks, "PostToolUse", postToolUse)
303	
304		// Also remove the metadata deny rule from permissions
305		var rawPermissions map[string]json.RawMessage
306		if permRaw, ok := rawSettings["permissions"]; ok {
307			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
308				// If parsing fails, just skip permissions cleanup
309				rawPermissions = nil
310			}
311		}
312	
313		if rawPermissions != nil {
314			if denyRaw, ok := rawPermissions["deny"]; ok {
315				var denyRules []string
316				if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
317					// Filter out the metadata deny rule
318					filteredRules := make([]string, 0, len(denyRules))
319					for _, rule := range denyRules {
320						if rule != metadataDenyRule {
321							filteredRules = append(filteredRules, rule)
322						}
323					}
324					if len(filteredRules) > 0 {
325						denyJSON, err := json.Marshal(filteredRules)
326						if err == nil {
327							rawPermissions["deny"] = denyJSON
328						}
329					} else {
330						// Remove empty deny array
331						delete(rawPermissions, "deny")
332					}
333				}
334			}
335	
336			// If permissions is empty, remove it entirely
337			if len(rawPermissions) > 0 {
338				permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
339				if err == nil {
340					rawSettings["permissions"] = permJSON
341				}
342			} else {
343				delete(rawSettings, "permissions")
344			}
345		}
346	
347		// Marshal hooks back (preserving unknown hook types)
348		if len(rawHooks) > 0 {
349			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
350			if err != nil {
351				return fmt.Errorf("failed to marshal hooks: %w", err)
352			}
353			rawSettings["hooks"] = hooksJSON
354		} else {
355			delete(rawSettings, "hooks")
356		}
357	
358		// Write back
359		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
360		if err != nil {
361			return fmt.Errorf("failed to marshal settings: %w", err)
362		}
363		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
364			return fmt.Errorf("failed to write settings.json: %w", err)
365		}
366		return nil
367	}
368	
369	// AreHooksInstalled checks if Entire hooks are installed.
370	func (c *ClaudeCodeAgent) AreHooksInstalled(ctx context.Context) bool {
371		// Use repo root to find .claude directory when run from a subdirectory
372		repoRoot, err := paths.WorktreeRoot(ctx)
373		if err != nil {
374			repoRoot = "." // Fallback to CWD if not in a git repo
375		}
376		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
377		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
378		if err != nil {
379			return false
380		}
381	
382		var settings ClaudeSettings
383		if err := json.Unmarshal(data, &settings); err != nil {
384			return false
385		}
386	
387		// Check for at least one of our hooks (new, wrapped, or legacy format)
388		return hasEntireHook(settings.Hooks.Stop)
389	}
390	
391	// Helper functions for hook management
392	
393	func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
394		for _, matcher := range matchers {
395			for _, hook := range matcher.Hooks {
396				if hook.Command == command {
397					return true
398				}
399			}
400		}
401		return false
402	}
403	
404	func hasEntireHook(matchers []ClaudeHookMatcher) bool {
405		for _, matcher := range matchers {
406			for _, hook := range matcher.Hooks {
407				if isEntireHook(hook.Command) {
408					return true
409				}
410			}
411		}
412		return false
413	}
414	
415	func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
416		for _, matcher := range matchers {
417			if matcher.Matcher == matcherName {
418				for _, hook := range matcher.Hooks {
419					if hook.Command == command {
420						return true
421					}
422				}
423			}
424		}
425		return false
426	}
427	
428	func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
429		entry := ClaudeHookEntry{
430			Type:    "command",
431			Command: command,
432		}
433	
434		// If no matcher name, add to a matcher with empty string
435		if matcherName == "" {
436			for i, matcher := range matchers {
437				if matcher.Matcher == "" {
438					matchers[i].Hooks = append(matchers[i].Hooks, entry)
439					return matchers
440				}
441			}
442			return append(matchers, ClaudeHookMatcher{
443				Matcher: "",
444				Hooks:   []ClaudeHookEntry{entry},
445			})
446		}
447	
448		// Find or create matcher with the given name
449		for i, matcher := range matchers {
450			if matcher.Matcher == matcherName {
451				matchers[i].Hooks = append(matchers[i].Hooks, entry)
452				return matchers
453			}
454		}
455	
456		return append(matchers, ClaudeHookMatcher{
457			Matcher: matcherName,
458			Hooks:   []ClaudeHookEntry{entry},
459		})
460	}
461	
462	// isEntireHook checks if a command is an Entire hook (old or new format)
463	func isEntireHook(command string) bool {
464		return agent.IsManagedHookCommand(command, entireHookPrefixes)
465	}
466	
467	// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
468	func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
469		result := make([]ClaudeHookMatcher, 0, len(matchers))
470		for _, matcher := range matchers {
471			filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
472			for _, hook := range matcher.Hooks {
473				if !isEntireHook(hook.Command) {
474					filteredHooks = append(filteredHooks, hook)
475				}
476			}
477			// Only keep the matcher if it has hooks remaining
478			if len(filteredHooks) > 0 {
479				matcher.Hooks = filteredHooks
480				result = append(result, matcher)
481			}
482		}
483		return result
484	}
485	
486	// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
487	// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
488	func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
489		// Same logic as removeEntireHooks - both work on the same structure
490		return removeEntireHooks(matchers)
491	}
492

