62		settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
63	
64		// Read existing settings if they exist
65		var rawSettings map[string]json.RawMessage
66	
67		// rawHooks preserves unknown hook types
68		var rawHooks map[string]json.RawMessage
69	
70		// rawPermissions preserves unknown permission fields (e.g., "ask")
71		var rawPermissions map[string]json.RawMessage
72	
73		existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from cwd + fixed path
74		if readErr == nil {
75			if err := json.Unmarshal(existingData, &rawSettings); err != nil {
76				return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
77			}
78			if hooksRaw, ok := rawSettings["hooks"]; ok {
79				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
80					return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
81				}
82			}
83			if permRaw, ok := rawSettings["permissions"]; ok {
84				if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
85					return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
86				}
87			}
88		} else {
89			rawSettings = make(map[string]json.RawMessage)
90		}
91	
92		if rawHooks == nil {
93			rawHooks = make(map[string]json.RawMessage)
94		}
95		if rawPermissions == nil {
96			rawPermissions = make(map[string]json.RawMessage)
97		}
98	
99		// Parse only the hook types we need to modify
100		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
101		parseHookType(rawHooks, "SessionStart", &sessionStart)
102		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
103		parseHookType(rawHooks, "Stop", &stop)
104		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
105		parseHookType(rawHooks, "PreToolUse", &preToolUse)
106		parseHookType(rawHooks, "PostToolUse", &postToolUse)
107		parseHookType(rawHooks, "PreCompact", &preCompact)
108	
109		// If force is true, remove all existing Entire hooks first
110		if force {
111			sessionStart = removeEntireHooks(sessionStart)
112			sessionEnd = removeEntireHooks(sessionEnd)
113			stop = removeEntireHooks(stop)
114			userPromptSubmit = removeEntireHooks(userPromptSubmit)
115			preToolUse = removeEntireHooks(preToolUse)
116			postToolUse = removeEntireHooks(postToolUse)
117			preCompact = removeEntireHooks(preCompact)
118		}
119	
120		// Define hook commands
121		var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, preCompactCmd string
122		localDevPrefix := `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go hooks factoryai-droid `
123		if localDev {
124			sessionStartCmd = localDevPrefix + "session-start"
125			sessionEndCmd = localDevPrefix + "session-end"
126			stopCmd = localDevPrefix + "stop"
127			userPromptSubmitCmd = localDevPrefix + "user-prompt-submit"
128			preTaskCmd = localDevPrefix + "pre-tool-use"
129			postTaskCmd = localDevPrefix + "post-tool-use"
130			preCompactCmd = localDevPrefix + "pre-compact"
131		} else {
132			sessionStartCmd = agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid session-start")
133			sessionEndCmd = agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid session-end")
134			stopCmd = agent.WrapProductionPlainTextWarningHookCommand("entire hooks factoryai-droid stop", agent.WarningFormatSingleLine)
135			userPromptSubmitCmd = agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid user-prompt-submit")
136			preTaskCmd = agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid pre-tool-use")
137			postTaskCmd = agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid post-tool-use")
138			preCompactCmd = agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid pre-compact")
139		}
140	
141		count := 0
142	
143		// Add hooks if they don't exist
144		if !hookCommandExists(sessionStart, sessionStartCmd) {
145			sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
146			count++
147		}
148		// Also install user-prompt-submit on SessionStart to ensure TurnStart fires
149		// even when UserPromptSubmit doesn't (e.g., droid exec mode).
150		// The user-prompt-submit handler gracefully handles SessionStart's stdin format
151		// (userPromptSubmitRaw is a superset of sessionInfoRaw; Prompt defaults to "").
152		if !hookCommandExists(sessionStart, userPromptSubmitCmd) {
153			sessionStart = addHookToMatcher(sessionStart, "", userPromptSubmitCmd)
154			count++
155		}
156		if !hookCommandExists(sessionEnd, sessionEndCmd) {
157			sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
158			count++
159		}
160		if !hookCommandExists(stop, stopCmd) {
161			stop = addHookToMatcher(stop, "", stopCmd)
162			count++
163		}
164		if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
165			userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
166			count++
167		}
168		if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
169			preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
170			count++
171		}
172		if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
173			postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
174			count++
175		}
176		if !hookCommandExists(preCompact, preCompactCmd) {
177			preCompact = addHookToMatcher(preCompact, "", preCompactCmd)
178			count++
179		}
180	
181		// Add permissions.deny rule if not present
182		permissionsChanged := false
183		var denyRules []string
184		if denyRaw, ok := rawPermissions["deny"]; ok {
185			if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
186				return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
187			}
188		}
189		if !slices.Contains(denyRules, metadataDenyRule) {
190			denyRules = append(denyRules, metadataDenyRule)
191			denyJSON, err := json.Marshal(denyRules)
192			if err != nil {
193				return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
194			}
195			rawPermissions["deny"] = denyJSON
196			permissionsChanged = true
197		}
198	
199		if count == 0 && !permissionsChanged {
200			return 0, nil // All hooks and permissions already installed
201		}
202	
203		// Marshal modified hook types back to rawHooks
204		marshalHookType(rawHooks, "SessionStart", sessionStart)
205		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
206		marshalHookType(rawHooks, "Stop", stop)
207		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
208		marshalHookType(rawHooks, "PreToolUse", preToolUse)
209		marshalHookType(rawHooks, "PostToolUse", postToolUse)
210		marshalHookType(rawHooks, "PreCompact", preCompact)
211	
212		// Marshal hooks and update raw settings
213		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
214		if err != nil {
215			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
216		}
217		rawSettings["hooks"] = hooksJSON
218	
219		// Marshal permissions and update raw settings
220		permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
221		if err != nil {
222			return 0, fmt.Errorf("failed to marshal permissions: %w", err)
223		}
224		rawSettings["permissions"] = permJSON
225	
226		// Write back to file
227		if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
228			return 0, fmt.Errorf("failed to create .factory directory: %w", err)
229		}
230	
231		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
232		if err != nil {
233			return 0, fmt.Errorf("failed to marshal settings: %w", err)
234		}
235	
236		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
237			return 0, fmt.Errorf("failed to write settings.json: %w", err)
238		}
239	
240		return count, nil
241	}
242	
243	// parseHookType parses a specific hook type from rawHooks into the target slice.
244	// Silently ignores parse errors (leaves target unchanged).
245	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]FactoryHookMatcher) {
246		if data, ok := rawHooks[hookType]; ok {
247			//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
248			json.Unmarshal(data, target)
249		}
250	}
251	
252	// marshalHookType marshals a hook type back to rawHooks.
253	// If the slice is empty, removes the key from rawHooks.
254	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []FactoryHookMatcher) {
255		if len(matchers) == 0 {
256			delete(rawHooks, hookType)
257			return
258		}
259		data, err := jsonutil.MarshalWithNoHTMLEscape(matchers)
260		if err != nil {
261			return // Silently ignore marshal errors (shouldn't happen)
262		}
263		rawHooks[hookType] = data
264	}
265	
266	// UninstallHooks removes Entire hooks from Factory AI Droid settings.
267	func (f *FactoryAIDroidAgent) UninstallHooks(ctx context.Context) error {
268		// Use repo root to find .factory directory when run from a subdirectory
269		repoRoot, err := paths.WorktreeRoot(ctx)
270		if err != nil {
271			repoRoot = "." // Fallback to CWD if not in a git repo
272		}
273		settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
274		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
275		if err != nil {
276			return nil //nolint:nilerr // No settings file means nothing to uninstall
277		}
278	
279		var rawSettings map[string]json.RawMessage
280		if err := json.Unmarshal(data, &rawSettings); err != nil {
281			return fmt.Errorf("failed to parse settings.json: %w", err)
282		}
283	
284		// rawHooks preserves unknown hook types
285		var rawHooks map[string]json.RawMessage
286		if hooksRaw, ok := rawSettings["hooks"]; ok {
287			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
288				return fmt.Errorf("failed to parse hooks: %w", err)
289			}
290		}
291		if rawHooks == nil {
292			rawHooks = make(map[string]json.RawMessage)
293		}
294	
295		// Parse only the hook types we need to modify
296		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
297		parseHookType(rawHooks, "SessionStart", &sessionStart)
298		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
299		parseHookType(rawHooks, "Stop", &stop)
300		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
301		parseHookType(rawHooks, "PreToolUse", &preToolUse)
302		parseHookType(rawHooks, "PostToolUse", &postToolUse)
303		parseHookType(rawHooks, "PreCompact", &preCompact)
304	
305		// Remove Entire hooks from all hook types
306		sessionStart = removeEntireHooks(sessionStart)
307		sessionEnd = removeEntireHooks(sessionEnd)
308		stop = removeEntireHooks(stop)
309		userPromptSubmit = removeEntireHooks(userPromptSubmit)
310		preToolUse = removeEntireHooks(preToolUse)
311		postToolUse = removeEntireHooks(postToolUse)
312		preCompact = removeEntireHooks(preCompact)
313	
314		// Marshal modified hook types back to rawHooks
315		marshalHookType(rawHooks, "SessionStart", sessionStart)
316		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
317		marshalHookType(rawHooks, "Stop", stop)
318		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
319		marshalHookType(rawHooks, "PreToolUse", preToolUse)
320		marshalHookType(rawHooks, "PostToolUse", postToolUse)
321		marshalHookType(rawHooks, "PreCompact", preCompact)
322	
323		// Also remove the metadata deny rule from permissions
324		var rawPermissions map[string]json.RawMessage
325		if permRaw, ok := rawSettings["permissions"]; ok {
326			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
327				// If parsing fails, just skip permissions cleanup
328				rawPermissions = nil
329			}
330		}
331	
332		if rawPermissions != nil {
333			if denyRaw, ok := rawPermissions["deny"]; ok {
334				var denyRules []string
335				if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
336					// Filter out the metadata deny rule
337					filteredRules := make([]string, 0, len(denyRules))
338					for _, rule := range denyRules {
339						if rule != metadataDenyRule {
340							filteredRules = append(filteredRules, rule)
341						}
342					}
343					if len(filteredRules) > 0 {
344						denyJSON, err := json.Marshal(filteredRules)
345						if err == nil {
346							rawPermissions["deny"] = denyJSON
347						}
348					} else {
349						// Remove empty deny array
350						delete(rawPermissions, "deny")
351					}
352				}
353			}
354	
355			// If permissions is empty, remove it entirely
356			if len(rawPermissions) > 0 {
357				permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
358				if err == nil {
359					rawSettings["permissions"] = permJSON
360				}
361			} else {
362				delete(rawSettings, "permissions")
363			}
364		}
365	
366		// Marshal hooks back (preserving unknown hook types)
367		if len(rawHooks) > 0 {
368			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
369			if err != nil {
370				return fmt.Errorf("failed to marshal hooks: %w", err)
371			}
372			rawSettings["hooks"] = hooksJSON
373		} else {
374			delete(rawSettings, "hooks")
375		}
376	
377		// Write back
378		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
379		if err != nil {
380			return fmt.Errorf("failed to marshal settings: %w", err)
381		}
382		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
383			return fmt.Errorf("failed to write settings.json: %w", err)
384		}
385		return nil
386	}
387	
388	// AreHooksInstalled checks if Entire hooks are installed.
389	func (f *FactoryAIDroidAgent) AreHooksInstalled(ctx context.Context) bool {
390		// Use repo root to find .factory directory when run from a subdirectory
391		repoRoot, err := paths.WorktreeRoot(ctx)
392		if err != nil {
393			repoRoot = "." // Fallback to CWD if not in a git repo
394		}
395		settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
396		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
397		if err != nil {
398			return false
399		}
400	
401		var settings FactorySettings
402		if err := json.Unmarshal(data, &settings); err != nil {
403			return false
404		}
405	
406		// Check for at least one of our hooks (production, wrapped, or local-dev format)
407		return hasEntireHook(settings.Hooks.Stop)
408	}
409	
410	// Helper functions for hook management
411	
412	func hookCommandExists(matchers []FactoryHookMatcher, command string) bool {
413		for _, matcher := range matchers {
414			for _, hook := range matcher.Hooks {
415				if hook.Command == command {
416					return true
417				}
418			}
419		}
420		return false
421	}
422	
423	func hasEntireHook(matchers []FactoryHookMatcher) bool {
424		for _, matcher := range matchers {
425			for _, hook := range matcher.Hooks {
426				if isEntireHook(hook.Command) {
427					return true
428				}
429			}
430		}
431		return false
432	}
433	
434	func hookCommandExistsWithMatcher(matchers []FactoryHookMatcher, matcherName, command string) bool {
435		for _, matcher := range matchers {
436			if matcher.Matcher == matcherName {
437				for _, hook := range matcher.Hooks {
438					if hook.Command == command {
439						return true
440					}
441				}
442			}
443		}
444		return false
445	}
446	
447	func addHookToMatcher(matchers []FactoryHookMatcher, matcherName, command string) []FactoryHookMatcher {
448		entry := FactoryHookEntry{Type: "command", Command: command}
449		for i := range matchers {
450			if matchers[i].Matcher == matcherName {
451				matchers[i].Hooks = append(matchers[i].Hooks, entry)
452				return matchers
453			}
454		}
455		return append(matchers, FactoryHookMatcher{Matcher: matcherName, Hooks: []FactoryHookEntry{entry}})
456	}
457	
458	// isEntireHook checks if a command is an Entire hook
459	func isEntireHook(command string) bool {
460		return agent.IsManagedHookCommand(command, entireHookPrefixes)
461	}
462	
463	// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
464	func removeEntireHooks(matchers []FactoryHookMatcher) []FactoryHookMatcher {
465		result := make([]FactoryHookMatcher, 0, len(matchers))
466		for _, matcher := range matchers {
467			filteredHooks := make([]FactoryHookEntry, 0, len(matcher.Hooks))
468			for _, hook := range matcher.Hooks {
469				if !isEntireHook(hook.Command) {
470					filteredHooks = append(filteredHooks, hook)
471				}
472			}
473			// Only keep the matcher if it has hooks remaining
474			if len(filteredHooks) > 0 {
475				matcher.Hooks = filteredHooks
476				result = append(result, matcher)
477			}
478		}
479		return result
480	}
