	raw, ok := rawSettings[HookMetaKey]
	if !ok {
		return HookMeta{}, false
	}
	var meta HookMeta
	if err := json.Unmarshal(raw, &meta); err != nil {
		return HookMeta{}, false
	}
	if meta.CLIVersion == "" {
		return HookMeta{}, false
	}
	return meta, true
}

