223	// AreHooksInstalled checks if Entire hooks are installed in Codex hooks.json.
224	func (c *CodexAgent) AreHooksInstalled(ctx context.Context) bool {
225		repoRoot, err := paths.WorktreeRoot(ctx)
226		if err != nil {
227			repoRoot = "."
228		}
229	
230		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
231		data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
232		if err != nil {
233			return false
234		}
235	
236		var hooksFile HooksFile
237		if err := json.Unmarshal(data, &hooksFile); err != nil {
238			return false
239		}
240	
241		return hasEntireHook(hooksFile.Hooks.SessionStart) &&
242			hasEntireHook(hooksFile.Hooks.UserPromptSubmit) &&
243			hasEntireHook(hooksFile.Hooks.Stop)
244	}
245	
246	// --- Helpers ---
247	
248	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]MatcherGroup) error {
249		if data, ok := rawHooks[hookType]; ok {
250			if err := json.Unmarshal(data, target); err != nil {
251				return fmt.Errorf("failed to parse %s hooks: %w", hookType, err)
252			}
253		}
254		return nil
255	}
256	
257	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, groups []MatcherGroup) {
258		if len(groups) == 0 {
259			delete(rawHooks, hookType)
260			return
261		}
262		data, err := jsonutil.MarshalWithNoHTMLEscape(groups)
263		if err != nil {
264			return
265		}
266		rawHooks[hookType] = data
267	}
268	
269	func hookCommandExists(groups []MatcherGroup, command string) bool {
270		for _, group := range groups {
271			for _, hook := range group.Hooks {
272				if hook.Command == command {
273					return true
274				}
275			}
276		}
277		return false
278	}
279	
280	func addHook(groups []MatcherGroup, command string) []MatcherGroup {
281		entry := HookEntry{
282			Type:    "command",
283			Command: command,
284			Timeout: 30,
285		}
286	
287		// Add to an existing group with null matcher, or create a new one
288		for i, group := range groups {
289			if group.Matcher == nil {
290				groups[i].Hooks = append(groups[i].Hooks, entry)
291				return groups
292			}
293		}
294		return append(groups, MatcherGroup{
295			Matcher: nil,
296			Hooks:   []HookEntry{entry},
297		})
298	}
299	
300	func isEntireHook(command string) bool {
301		return agent.IsManagedHookCommand(command, entireHookPrefixes)
302	}
303	
304	func hasEntireHook(groups []MatcherGroup) bool {
305		for _, group := range groups {
306			for _, hook := range group.Hooks {
307				if isEntireHook(hook.Command) {
308					return true
309				}
310			}
311		}
312		return false
313	}
314	
315	func removeEntireHooks(groups []MatcherGroup) []MatcherGroup {
316		result := make([]MatcherGroup, 0, len(groups))
317		for _, group := range groups {
318			filtered := make([]HookEntry, 0, len(group.Hooks))
319			for _, hook := range group.Hooks {
320				if !isEntireHook(hook.Command) {
321					filtered = append(filtered, hook)
322				}
323			}
324			if len(filtered) > 0 {
325				group.Hooks = filtered
326				result = append(result, group)
327			}
328		}
329		return result
330	}
331	
332	// configFileName is the Codex config file name.
333	const configFileName = "config.toml"
334	
335	// featureLine is the TOML line that enables the codex_hooks feature.
336	const featureLine = "codex_hooks = true"
337	
338	// ensureProjectFeatureEnabled writes features.codex_hooks = true to the
339	// project-level .codex/config.toml. This keeps the feature flag per-repo.
340	func ensureProjectFeatureEnabled(repoRoot string) error {
341		configPath := filepath.Join(repoRoot, ".codex", configFileName)
342	
343		data, err := os.ReadFile(configPath) //nolint:gosec // path constructed from repo root
344		if err != nil && !os.IsNotExist(err) {
345			return fmt.Errorf("failed to read config.toml: %w", err)
346		}
347	
348		content := string(data)
349		if strings.Contains(content, featureLine) {
350			return nil
351		}
352	
353		if strings.Contains(content, "[features]") {
354			content = strings.Replace(content, "[features]", "[features]\n"+featureLine, 1)
355		} else {
356			if len(content) > 0 && !strings.HasSuffix(content, "\n") {
357				content += "\n"
358			}
359			content += "\n[features]\n" + featureLine + "\n"
360		}
361	
362		if err := os.MkdirAll(filepath.Dir(configPath), 0o750); err != nil {
363			return fmt.Errorf("failed to create .codex directory: %w", err)
364		}
365		if err := os.WriteFile(configPath, []byte(content), 0o600); err != nil { //nolint:gosec // path constructed from repo root
366			return fmt.Errorf("failed to write config.toml: %w", err)
367		}
368		return nil
369	}
